javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const colName = event.payload.context.columnKey;
    if (colName === 'name') {
        var route = null;
        var url = null;
        var fields = null;
        var params = null;
        const artifactId = event.payload.context.row.cells.document_id.metadata.internalValue;
        const artifactTable = event.payload.context.row.cells.table_name.value;
        switch (artifactTable) {
            case 'par_dashboard':
                route = 'dashboards';
                params = {
                sysId: artifactId
                };
                break;
            case 'par_visualization':
                route = 'visualization-designer';
                fields = {
                sysid: artifactId
                };
                break;
            case 'pa_indicators': 
                route = 'ac_kpi_details';
                fields = {
                uuid: artifactId
                };
                break;
            case 'pa_dashboards':
                url = "now/nav/ui/classic/params/target/%24pa_dashboard.do%3Fsysparm_dashboard%3D" + artifactId;
                break;
            case 'sys_report':
                url = "now/nav/ui/classic/params/target/sys_report_template.do%3Fjvar_report_id%3D" + artifactId;
                break;
            default:
                break;
        }
        return {
            route: route,
            fields: fields,
            params: params,
            redirect: null,
            passiveNavigation: null,
            title: null,
            multiInstField: null,
            targetRoute: null,
            external: url ? {
                url: url,
                target: '_self',
            } : null,
            navigationOptions: null
        };
    }

    return {
        route: null,
        fields: null,
        params: null,
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: null,
        external: null,
        navigationOptions: null
    };
})

